  constructor() {
    this.highQueue = [];
    this.lowQueue = [];
    this.lowDelayMs = 0;
    this._delayTimer = null;
    this.isProcessing = false;
  }

  async enqueue(url, options) {
    options = options || {};
    return new Promise((resolve, reject) => {
      this.highQueue.push({ url, options, resolve, reject });
      this._cancelDelay();
      this.processNext();
    });
  }

  /**
